require __DIR__ . '/../config/auth.php'; require_admin(); require __DIR__ . '/../config/database.php';
if($_SERVER['REQUEST_METHOD']==='POST'){ $id=(int)($_POST['id']??0);$status=$_POST['status']??'Pending';if(in_array($status,['Pending','Processing','Completed','Cancelled'],true)){$pdo->prepare('UPDATE orders SET status=? WHERE id=?')->execute([$status,$id]);}}
