?><!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>Orders</title><style>body{font-family:Poppins,Arial,sans-serif;background:#f4f6f8;margin:0}.top{background:#0508d0;color:#fff;padding:18px 5%}.top a{color:#fff}.wrap{width:94%;margin:25px auto;background:#fff;padding:20px;border-radius:15px;overflow:auto}table{width:100%;border-collapse:collapse;min-width:950px}th,td{padding:11px;border-bottom:1px solid #eee;text-align:left;vertical-align:top}th{background:#f1f3f5}select,button{padding:8px;border-radius:7px;border:1px solid #ccc}button{background:#0508d0;color:#fff;border:0}</style></head><body><header class="top"><h2>Customer Orders</h2><a href="dashboard.php">← Dashboard</a></header><main class="wrap"><table><tr><th>Name</th><th>Phone</th><th>Address</th><th>Product</th><th>Qty</th><th>Details</th><th>Status</th><th>Date</th></tr><?php foreach($orders as $o): ?><tr><td><?=htmlspecialchars($o['full_name'])?></td><td><?=htmlspecialchars($o['phone'])?></td><td><?=htmlspecialchars($o['address'])?></td><td><?=htmlspecialchars($o['product'])?></td><td><?=$o['quantity']?></td><td><?=htmlspecialchars($o['message'])?></td><td><form method="post"><input type="hidden" name="id" value="<?=$o['id']?>"><select name="status"><option <?=$o['status']=='Pending'?'selected':''?>>Pending</option><option <?=$o['status']=='Processing'?'selected':''?>>Processing</option><option <?=$o['status']=='Completed'?'selected':''?>>Completed</option><option <?=$o['status']=='Cancelled'?'selected':''?>>Cancelled</option></select><button>Save</button></form></td><td><?=htmlspecialchars($o['created_at'])?></td></tr><?php endforeach; ?></table></main></body></html>
